import type { SurveyExport } from '../models/survey-export';
import type { Unsubscribe } from './survey-repository';

/** Backend-built export archives (e.g. generated by a Cloud Function). */
export interface SurveyExportRepository {
  /** Latest export record, read from the backend (not a local cache). */
  getLatest(surveyId: string): Promise<SurveyExport | null>;
  subscribeLatest(surveyId: string, callback: (value: SurveyExport | null) => void): Unsubscribe;
  /** Ask the backend to (re)build; the returned id is echoed as `lastRequestId` when answered. */
  requestExport(surveyId: string): Promise<string>;
}
